			["actions"] = {
				["start"] = {
				},
				["finish"] = {
				},
				["init"] = {
					["custom"] = "local pref = \"prof\"\nfor _, char in pairs(aura_env.config.perChar) do\n    if char.name == UnitName'player' then\n        pref = ({\"prof\", \"paragon\", \"none\"})[char.goal]\n        break\n    end\nend\nDebugPrint('preferences set to '..pref)\n\nlocal goals = setmetatable(\n    {\n        -- always want to get feast/siege/hunts\n        [2511] = {3},\n        [2503] = {5},\n        [2510] = {5},\n    },\n    {\n        __index = function(t, k)\n            t[k] = {} \n            return t[k] \n        end\n    }\n)\n\n\nfor _, id in pairs(C_MajorFactions.GetMajorFactionIDs()) do\n    local level = goals[id][#goals[id]] or 1\n    local rewards\n    repeat\n        rewards = C_MajorFactions.GetRenownRewardsForLevel(id, level)\n        if pref == \"prof\" then\n            for  _, reward in ipairs(rewards or {}) do\n                if reward.toastDescription then\n                    local found = false\n                    if reward.toastDescription:find(\"Recipe\") then\n                        found = true\n                        DebugPrint'found recipe'\n                    elseif reward.toastDescription:find(\"Specialization\") then\n                        found = true\n                        DebugPrint'found knowledge'\n                    end\n                    if found then\n                        table.insert(goals[id], level)\n                    end\n                    \n                end\n            end\n        end\n        level = level + 1\n        \n    until not rewards or #rewards == 0\n    if pref == \"paragon\" then\n        table.insert(goals[id], level - 2)\n    end\nend\nDebugPrint(goals)\n\n\nlocal function update(state, key, value)\n    if state[key] ~= value then\n        state.changed = true\n        state[key] = value\n    end\nend\n\nfunction aura_env.dataToState(id, state)\n    local data = C_MajorFactions.GetMajorFactionData(id)\n    local nextGoal\n    DebugPrint('starting to iterate thru', goals[id])\n    for _, goal in ipairs(goals[id]) do\n        if data.renownLevel < goal then\n            nextGoal = goal\n            DebugPrint(\"found goal:\", nextGoal)\n            break\n        end\n    end\n    if not nextGoal then\n        if state then\n            state.changed = true\n            state.show = false\n            DebugPrint(state)\n        end\n        return  state, true\n    end\n    state = state or {}\n    update(state, \"progressType\" , \"static\")\n    update(state, \"show\", true)\n    update(state, \"level\", data.renownLevel)\n    update(state, \"name\", data.name)\n    update(state, \"value\", C_MajorFactions.HasMaximumRenown(id) and data.renownLevelThreshold or data.renownReputationEarned)\n    update(state, \"order\", data.unlockOrder)\n    update(state, \"total\",  data.renownLevelThreshold)\n    update(state, \"goal\", nextGoal)\n    update(state, \"finalGoal\", goals[id][#goals[id]])\n    --    DebugPrint(state)\n    return state, state.changed\nend",
					["do_custom"] = true,
				},
			},
