			["barColor"] = {
				0.37647062540054, -- [1]
				0.93725496530533, -- [2]
				0.37647062540054, -- [3]
				1, -- [4]
			},
			["desc"] = "- Left text: show percentage of damage that goes into stagger, adjusted to current target.\n\n- Middle text: shows damage taken from stagger per tick.\n\n-Right text: Damage in stagger % of maxhealth.",
			["sparkOffsetY"] = 0,
			["gradientOrientation"] = "HORIZONTAL",
			["load"] = {
				["use_petbattle"] = false,
				["use_never"] = false,
				["class"] = {
					["single"] = "MONK",
					["multi"] = {
