			["useAdjustededMax"] = false,
			["width"] = 405,
			["source"] = "import",
			["url"] = "https://wago.io/LuxthosDeathKnightDragonflight/67",
			["color"] = {
				0, -- [1]
				0, -- [2]
				0, -- [3]
