			["preferToUpdate"] = true,
			["customText"] = "function ()\n    for i = 1,4 do\n        local ShieldUnit = \"party\" .. i\n        if(UnitExists(ShieldUnit)) then\n            \n            local shield, _ = WA_GetUnitBuff(ShieldUnit, \"Life Cocoon\", nil, \"PLAYER\")\n            \n            if shield then\n                \n                \n                return aura_env.ShortenNumber(select(16, WA_GetUnitBuff(ShieldUnit, \"Life Cocoon\", nil, \"PLAYER\")))\n            end\n        end\n    end\n    \n    \n    \n    local shield, _ = WA_GetUnitBuff(\"player\", \"Life Cocoon\", nil, \"PLAYER\")\n    \n    return aura_env.ShortenNumber(select(16, WA_GetUnitBuff(\"player\", \"Life Cocoon\", nil, \"PLAYER\")))\nend",
