				{
					["trigger"] = {
						["type"] = "custom",
						["custom"] = "function( as, _, _, sE, _, sId, _, _, _, dId, _, _, _, spId )\n    if sId == UnitGUID( \"player\" ) and spId == 1943 then --Player Rupture\n        as[ \"\" ] = { \n            show = true,\n            changed = true,\n            destGUID = dId,\n            isRemoval = ( sE == \"SPELL_AURA_REMOVED\" ) or false,\n            eventTime = GetTime()\n        }\n        return true\n    end\nend",
						["custom_type"] = "stateupdate",
