						["type"] = "custom",
						["custom"] = "function( as, _, _, sE, _, sId, _, _, _, _, _, _, _, spId, spNm )\n    if sId == UnitGUID( \"player\" ) then --Player cast\n        if aura_env.rogueGCDs[ spId ] then\n            as[ \"\" ] = {\n                show = true,\n                changed = true,\n                spellId = spId,\n                name = spNm,\n                castTime = GetTime(),\n                expirationTime = GetTime() + 1,\n            }\n            return true\n        end\n    end\nend",
