						["check"] = "event",
						["unit"] = "player",
						["custom"] = "-- Created by Dsune\nfunction(allstates, event, triggerNum, triggerStates)\n    \n    if event == \"TRIGGER\" and triggerNum then\n        -- remove from allstates states missing from trigger 1\n        for key, state in pairs(allstates) do\n            if not triggerStates[key] then\n                state.show = false\n                state.changed = true\n            end\n        end\n        for k, v in pairs(triggerStates) do\n            allstates[\"\"] = allstates[\"\"] or {}\n            local state = allstates[\"\"]\n            if not state.expirationTime then \n                for key, data in pairs(v) do\n                    if state[key] ~= data then\n                        state[key] = data\n                        state.changed = true\n                    end\n                end\n            elseif state.refreshTime == v.refreshTime then\n                for key, data in pairs(v) do\n                    if key ~= \"duration\" and state[key] ~= data then\n                        state[key] = data\n                        state.changed = true\n                    end\n                end\n            else\n                for key, data in pairs(v) do\n                    if key~= \"duration\" and state[key] ~= data then\n                        state[key] = data\n                        state.changed = true\n                    elseif key == \"duration\" and state.expirationTime ~= v.expirationTime then\n                        if state.duration ~= v.expirationTime-GetTime() then\n                            state.duration =  v.expirationTime - GetTime()\n                            state.changed = true\n                        end\n                    end\n                end\n            end\n        end\n        return true\n    end\nend\n\n\n",
