		["Orbit Breaker "] = {
			["iconSource"] = 0,
			["wagoID"] = "ryBp05DHX",
			["color"] = {
				1, -- [1]
				1, -- [2]
				1, -- [3]
				1, -- [4]
			},
			["preferToUpdate"] = false,
			["yOffset"] = 0,
			["anchorPoint"] = "CENTER",
			["cooldownSwipe"] = true,
			["cooldownEdge"] = true,
			["actions"] = {
				["start"] = {
				},
				["init"] = {
					["custom"] = "aura_env.firstRunTextPrefix = '' -- the text that will prefix the count on the firstRun - e.g \"\" or \"?\"\n\naura_env.spellIds = {\n    fullMoon  =  274283;\n    shootingStars =  202497;\n    crashingStar = 408310;\n    convoke = 391528;\n    convokeDF = 12345\n}\n\naura_env.procCount = 30\n\naura_env.UAPB_OB_DELAY = 0.1 -- delay before checking if hardcast or proc. 0.1 should be a reasonable value\n\n\nif not aura_env.saved then\n    aura_env.saved = {}\nend\n\nif not aura_env.saved.stacks then\n    aura_env.saved.stacks = 0\nend\n\nif not aura_env.saved.firstRun then\n    aura_env.saved.firstRun = true\nend\n\naura_env.setStacks = function(s)\n    s = s % aura_env.procCount\n    aura_env.saved.stacks = s\n    \n    WeakAuras.ScanEvents(\"UAPB_OB_STACKS\", s)\n    \n    return s\nend\n\naura_env.handleLogin = function(state)\n    \n    state.stacks = aura_env.setStacks(0)\n    state.value = state.stacks\n    state.changed = true\n    \n    return state\nend\n\naura_env.handleSpellDamage = function(state)\n    \n    state.stacks = aura_env.setStacks(state.stacks + 1)\n    state.value = state.stacks\n    state.text = state.stacks\n    state.changed = true    \n    \n    return state\nend\n\naura_env.handleSpellChannelStart = function(state, spellId)\n    \n    if spellId == aura_env.spellIds.convoke then\n        state.convoke = true\n    end \n    \nend\n\naura_env.handleSpellChannelStop = function(state, spellId)\n    \n    if spellId == aura_env.spellIds.convoke then\n        C_Timer.After(aura_env.UAPB_OB_DELAY, function()\n                state.convoke = false\n        end)\n    end\n    \nend\n\n\naura_env.handleEnergized = function(state)\n    \n    state.energized = state.energized + 1\n    state.changed = true\n    \n    -- send delayed event since this event fires for both proc and cast\n    C_Timer.After(aura_env.UAPB_OB_DELAY, function()\n            WeakAuras.ScanEvents(\"UAPB_OB_DELAY\", aura_env.id)  \n    end)\n    \n    return state\nend\n\naura_env.handleSpellCastSuccess = function(state)\n    \n    state.cast = true -- full moon was hardcast\n    state.changed = true\n    \n    return state\nend\n\n\naura_env.handleDelay = function(state)\n    \n    if aura_env.stacksShouldReset(state) then\n        \n        state.stacks = aura_env.resetStacks(state)\n        state.value = state.stacks\n        state.text = state.stacks\n        state.firstRun = false\n        \n    else   \n        \n        state.cast = false -- this was a hard cast full moon, reset the value\n    end\n    \n    state.energized = state.energized - 1        \n    state.changed = true\n    \n    return state\nend\n\n\naura_env.stacksShouldReset = function(state)\n    \n    return not state.convoke             -- we cant differentiate OB proc or convoke proc\n    and (not state.cast and state.energized == 1) -- proc\n    or ( state.cast and state.energized == 2) -- proc, then full moon cast within delay time\nend\n\n\naura_env.resetStacks = function(state)\n    return aura_env.setStacks(0)\nend",
					["do_custom"] = true,
				},
				["finish"] = {
				},
			},
			["triggers"] = {
				{
					["trigger"] = {
						["type"] = "custom",
						["custom_type"] = "stateupdate",
						["customVariables"] = "{\n    firstRun = {\n        type = \"bool\",\n        display = \"First Run / Learning\"\n    },\n    stacks = true\n}",
						["event"] = "Health",
						["unit"] = "player",
						["subeventSuffix"] = "_CAST_START",
						["subeventPrefix"] = "SPELL",
						["events"] = "CLEU:SPELL_ENERGIZE:SPELL_CAST_SUCCESS:SPELL_DAMAGE UNIT_SPELLCAST_CHANNEL_START:player UNIT_SPELLCAST_CHANNEL_STOP:player UAPB_OB_DELAY PLAYER_ENTERING_WORLD WA_DELAYED_PLAYER_ENTERING_WORLD",
						["names"] = {
						},
						["check"] = "event",
						["spellIds"] = {
						},
						["custom"] = "function(s, event, ...)\n    \n    if not s[\"\"] then\n        \n        s[\"\"] = {\n            show = true,\n            changed = false,            \n            stacks = aura_env.saved.stacks or 0, -- shooting stars count\n            firstRun = true, -- aura_env.saved.firstRun  or true, -- we need to track our first run, as opening the UI/reload will reset stacks and may be invalid\n            text = aura_env.firstRunTextPrefix,\n            cast = false, -- was full moon hardcast\n            energized = 0, -- full moon energized count\n            convoke = false, \n            \n            total = aura_env.procCount,\n            value = aura_env.saved.stacks or 0, -- shooting stars count\n            progressType = \"static\"\n        }\n        \n        return true \n    end\n    \n    if event == \"PLAYER_ENTERING_WORLD\" or event == \"WA_DELAYED_PLAYER_ENTERING_WORLD\" then\n        \n        local login, _ = ...\n        \n        if login then \n            s[\"\"] = aura_env.handleLogin(s[\"\"])\n            return true\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_CHANNEL_START\" then\n        local _,_,spellId = ...        \n        aura_env.handleSpellChannelStart(s[\"\"], spellId)\n        \n    elseif event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        local _,_,spellId = ...\n        aura_env.handleSpellChannelStop(s[\"\"], spellId)\n        \n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        local _,subevent,_,sourceGUID,_,_,_,_,_,_,_,spellID = ...\n        \n        if sourceGUID == UnitGUID(\"player\") then\n            \n            if subevent == \"SPELL_DAMAGE\" and \n            (spellID == aura_env.spellIds.shootingStars or \n            spellID == aura_env.spellIds.crashingStar) then\n                s[\"\"] = aura_env.handleSpellDamage(s[\"\"])\n                \n            elseif subevent == \"SPELL_ENERGIZE\" and spellID == aura_env.spellIds.fullMoon then\n                s[\"\"] = aura_env.handleEnergized(s[\"\"])\n                \n            elseif subevent == \"SPELL_CAST_SUCCESS\" and spellID == aura_env.spellIds.fullMoon then\n                s[\"\"] = aura_env.handleSpellCastSuccess(s[\"\"])     \n            end\n            \n            return true\n        end\n        \n    elseif event == \"UAPB_OB_DELAY\" and ... == aura_env.id then\n        s[\"\"] = aura_env.handleDelay(s[\"\"])\n        return true\n    end\n    \nend",
						["debuffType"] = "HELPFUL",
					},
					["untrigger"] = {
