			["anchorFrameParent"] = true,
			["texture"] = "Interface\\AddOns\\WeakAuras\\Media\\Textures\\Square_White_Border",
			["alpha"] = 1,
			["cooldownTextDisabled"] = false,
			["semver"] = "1.0.5",
			["tocversion"] = 100200,
			["id"] = "DT - Darkheart Thicket",
			["useCooldownModRate"] = true,
			["frameStrata"] = 1,
			["width"] = 32,
			["zoom"] = 0.3,
			["config"] = {
				["dungeon"] = false,
				["expansion"] = false,
				["mythic"] = true,
			},
			["inverse"] = true,
			["selfPoint"] = "CENTER",
			["conditions"] = {
			},
			["information"] = {
				["forceEvents"] = true,
				["ignoreOptionsEventErrors"] = true,
			},
			["actions"] = {
				["start"] = {
					["custom"] = "aura_env.button = CreateFrame(\"Button\", nil, WeakAuras.regions[aura_env.id].region, \"SecureActionButtonTemplate\")\naura_env.button:SetAllPoints(WeakAuras.regions[aura_env.id].region)\n\nWeakAuras.ScanEvents(\"LEGION\", true)\n\naura_env.setButtonAttributes = function()\n    if InCombatLockdown() then\n        print(\"please reload for new teleport button\")\n        return\n    else\n        local i = 1\n        while GetSpellBookItemName(i, BOOKTYPE_SPELL) do\n            local spellName, spellSubName, spellID = GetSpellBookItemName(i, BOOKTYPE_SPELL)\n            if spellID == aura_env.spellID then break end\n            i = i + 1\n        end\n        aura_env.button:Show()\n        aura_env.button:RegisterForClicks(\"LeftButtonDown\", \"LeftButtonUp\")\n        aura_env.button:SetAttribute(\"type\", \"spell\")\n        aura_env.button:SetAttribute(\"spell\", aura_env.spellID)\n        aura_env.button:SetScript(\"OnEnter\", function(self)\n                GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n                GameTooltip:ClearLines()\n                GameTooltip:SetSpellBookItem(i, BOOKTYPE_SPELL)\n                GameTooltip:Show()\n        end)\n        aura_env.button:SetScript(\"OnLeave\", function(self)\n                GameTooltip:Hide()\n        end)\n    end\n    \nend\n\naura_env.setButtonAttributes()",
					["do_custom"] = true,
				},
				["finish"] = {
				},
				["init"] = {
					["custom"] = "aura_env.spellID = 424163",
					["do_custom"] = true,
				},
			},
		},
		["Rallying Cry EXT"] = {
