s={74114}, optionKey=\"skinning\", skillID=393},\n    {name=\"Draconic Treatise (Tailoring)\", quests={74115}, optionKey=\"tailoring\", skillID=197},\n    \n    {name=\"Valdrakken Profession Quests (Alchemy)\", quests={66937, 66938, 66940, 70530, 70532, 70531, 70533, 72427, 75363, 75371, 77932, 77933}, optionKey=\"alchemy\", skillID=171, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Blacksmithing)\", quests={66517, 66897, 66941, 70211, 70233, 70234, 70235, 72398, 75148, 75569, 77935, 77936}, optionKey=\"blacksmithing\", skillID=164, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Enchanting)\", quests={66884, 66900, 66935, 72155, 72172, 72173, 72175, 72423, 75150, 75865, 77910, 77937}, optionKey=\"enchanting\", skillID=333, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Engineering)\", quests={66890, 66891, 66942, 70539, 70540, 70545, 70557, 72396, 75575, 75608, 77891, 77938}, optionKey=\"engineering\", skillID=202, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Herbalism)\", quests={70613, 70614, 70615, 70616}, optionKey=\"herbalism\", skillID=182, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Inscription)\", quests={66943, 66944, 66945, 70558, 70559, 70560, 70561, 72438, 75149, 75573, 77889, 77914}, optionKey=\"inscription\", skillID=773, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Jewelcrafting)\", quests={66516, 66949, 66950, 70562, 70563, 70564, 70565, 72428, 75362, 75602, 77892, 77912}, optionKey=\"jewelcrafting\", skillID=755, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Leatherworking)\", quests={66363, 66364, 66951, 70567, 70568, 70569, 70571, 72407, 75354, 75368, 77945, 77946}, optionKey=\"leatherworking\", skillID=165, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Mining)\", quests={70617, 70618, 72156, 72157}, optionKey=\"mining\", skillID=186, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Skinning)\", quests={70619, 70620, 72158, 72159}, optionKey=\"skinning\", skillID=393, useWorldState=true},\n    {name=\"Valdrakken Profession Quests (Tailoring)\", quests={66899, 66952, 66953, 70572, 70582, 70586, 70587, 72410, 75407, 75600, 77947, 77949}, optionKey=\"tailoring\", skillID=197, useWorldState=true},\n    \n    {name=\"Crafting Order Quest (Blacksmithing)\", quests={70589}, optionKey=\"blacksmithing\", skillID=164},\n    {name=\"Crafting Order Quest (Engineering)\", quests={70591}, optionKey=\"engineering\", skillID=202},\n    {name=\"Crafting Order Quest (Inscription)\", quests={70592}, optionKey=\"inscription\", skillID=773},\n    {name=\"Crafting Order Quest (Jewelcrafting)\", quests={70593}, optionKey=\"jewelcrafting\", skillID=755},\n    {name=\"Crafting Order Quest (Leatherworking)\", quests={70594}, optionKey=\"leatherworking\", skillID=165},\n    {name=\"Crafting Order Quest (Tailoring)\", quests={70595}, optionKey=\"tailoring\", skillID=197},\n    \n    {name=\"Darkmoon Faire Quest (Alchemy)\", quests={29506}, optionKey=\"alchemy\", skillID=171, DMF=true},\n    {name=\"Darkmoon Faire Quest (Blacksmithing)\", quests={29508}, optionKey=\"blacksmithing\", skillID=164, DMF=true},\n    {name=\"Darkmoon Faire Quest (Enchanting)\", quests={29510}, optionKey=\"enchanting\", skillID=333, DMF=true},\n    {name=\"Darkmoon Faire Quest (Engineering)\", quests={29511}, optionKey=\"engineering\", skillID=202, DMF=true},\n    {name=\"Darkmoon Faire Quest (Herbalism)\", quests={29514}, optionKey=\"herbalism\", skillID=182, DMF=true},\n    {name=\"Darkmoon Faire Quest (Inscription)\", quests={29515}, optionKey=\"inscription\", skillID=773, DMF=true},\n    {name=\"Darkmoon Faire Quest (Jewelcrafting)\", quests={29516}, optionKey=\"jewelcrafting\", skillID=755, DMF=true},\n    {name=\"Darkmoon Faire Quest (Leatherworking)\", quests={29517}, optionKey=\"leatherworking\", skillID=165, DMF=true},\n    {name=\"Darkmoon Faire Quest (Mining)\", quests={29518}, optionKey=\"mining\", skillID=186, DMF=true},\n    {name=\"Darkmoon Faire Quest (Skinning)\", quests={29519}, optionKey=\"skinning\", skillID=393, DMF=true},\n    {name=\"Darkmoon Faire Quest (Tailoring)\", quests={29520}, optionKey=\"tailoring\", skillID=197, DMF=true},\n}\n\n-- check to see if the Faire is active\nlocal function CheckDarkmoonOpen()\n    local i\n    local DARKMOON_EVENT_ID = 479\n    local date = C_DateAndTime.GetCurrentCalendarTime()\n    local today = date.monthDay\n    local numDayEvents = C_Calendar.GetNumDayEvents(0, today)\n    for i = 1,numDayEvents do\n        local title = C_Calendar.GetDayEvent(0, today, i).eventID\n        if title == DARKMOON_EVENT_ID then\n            return true\n        end\n    end\n    return false\nend\n\n-- This returns true if at least one of the required quests is currently active.\nlocal is_active = function(objective)\n    if not aura_env.config[objective.optionKey] then\n        return false\n    end\n    if not objective.required_quests then\n        return true\n    end\n    for _, q in ipairs(objective.required_quests) do\n        if C_TaskQuest.GetQuestTimeLeftSeconds(q) or C_QuestLog.IsQuestFlaggedCompleted(q) then\n            return true\n        end\n    end\nend\n\n-- This returns the number of quests that are not complete.\nlocal remaining_quests = function(objective)\n    local c = #objective.quests\n    if objective.useWorldState then \n        if objective.skillID == 182 or objective.skillID == 186 or objective.skillID == 393 then\n            c = 1\n            for _, q in ipairs(objective.quests) do\n                if C_QuestLog.IsQuestFlaggedCompleted(q) then\n                    c = c - 1\n                end\n            end\n        else\n            c = 2\n            for _, q in ipairs(objective.quests) do\n                if C_QuestLog.IsQuestFlaggedCompleted(q) then\n                    c = c - 1\n                end\n            end\n        end\n    elseif objective.DMF then\n        if CheckDarkmoonOpen() then      \n            for _, q in ipairs(objective.quests) do\n                if C_QuestLog.IsQuestFlaggedCompleted(q) then\n                    c = c - 1\n                end\n            end\n        else \n            c=0\n        end\n    else\n        for _, q in ipairs(objective.quests) do\n            if C_QuestLog.IsQuestFlaggedCompleted(q) then\n                c = c - 1\n            end\n        end\n    end\n    return c\nend\n\nlocal profession_known = function(objective)\n    local prof1, prof2 = GetProfessions()\n    local prof1SkillID, prof2SkillID, _\n    if (prof1 ~= nil) then\n        _,_,_,_,_,_,prof1SkillID = GetProfessionInfo(prof1)\n    end\n    if (prof2 ~= nil) then\n        _,_,_,_,_,_,prof2SkillID = GetProfessionInfo(prof2)\n    end\n    if (objective.skillID == prof1SkillID) or (objective.skillID == prof2SkillID) then\n        return true\n    else\n        if not aura_env.config[\"automaticDetection\"] then\n            return true\n        else\n            return false\n        end\n    end\nend\n\naura_env.update_display = function()\n    aura_env.text = nil\n    for _, objective in ipairs(objectives) do\n        if is_active(objective) and profession_known(objective) then\n            local c = remaining_quests(objective)\n            if c > 0 then\n                if aura_env.text then\n                    aura_env.text = aura_env.text .. \"\\n\" .. objective.name .. \": \" .. c\n                else\n                    aura_env.text = objective.name .. \": \" .. c\n                end\n            end\n        end\n    end\nend\n\naura_env.update_display()",
					["do_custom"] = true,
				},
