			["actions"] = {
				["start"] = {
					["custom"] = "aura_env.button = CreateFrame(\"Button\", nil, WeakAuras.regions[aura_env.id].region, \"SecureActionButtonTemplate\")\naura_env.button:SetAllPoints(WeakAuras.regions[aura_env.id].region)\n\nWeakAuras.ScanEvents(\"BFA\", true)\n\naura_env.setButtonAttributes = function()\n    if InCombatLockdown() then\n        print(\"please reload for new teleport button\")\n        return\n    else\n        local i = 1\n        while GetSpellBookItemName(i, BOOKTYPE_SPELL) do\n            local spellName, spellSubName, spellID = GetSpellBookItemName(i, BOOKTYPE_SPELL)\n            if spellID == aura_env.spellID then break end\n            i = i + 1\n        end\n        aura_env.button:Show()\n        aura_env.button:RegisterForClicks(\"LeftButtonDown\", \"LeftButtonUp\")\n        aura_env.button:SetAttribute(\"type\", \"spell\")\n        aura_env.button:SetAttribute(\"spell\", aura_env.spellID)\n        aura_env.button:SetScript(\"OnEnter\", function(self)\n                GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n                GameTooltip:ClearLines()\n                GameTooltip:SetSpellBookItem(i, BOOKTYPE_SPELL)\n                GameTooltip:Show()\n        end)\n        aura_env.button:SetScript(\"OnLeave\", function(self)\n                GameTooltip:Hide()\n        end)\n    end\n    \nend\n\naura_env.setButtonAttributes()",
