			["anchorFrameParent"] = true,
			["texture"] = "Interface\\AddOns\\WeakAuras\\Media\\Textures\\Square_White_Border",
			["alpha"] = 1,
			["cooldownTextDisabled"] = false,
			["semver"] = "1.0.5",
			["tocversion"] = 100200,
			["id"] = "DT - De Other Side",
			["useCooldownModRate"] = true,
			["frameStrata"] = 1,
			["width"] = 32,
			["zoom"] = 0.3,
			["config"] = {
				["dungeon"] = false,
				["expansion"] = false,
			},
			["inverse"] = true,
			["selfPoint"] = "CENTER",
			["conditions"] = {
			},
			["information"] = {
				["forceEvents"] = true,
				["ignoreOptionsEventErrors"] = true,
			},
			["actions"] = {
				["start"] = {
					["custom"] = "aura_env.button = CreateFrame(\"Button\", nil, WeakAuras.regions[aura_env.id].region, \"SecureActionButtonTemplate\")\naura_env.button:SetAllPoints(WeakAuras.regions[aura_env.id].region)\n\nWeakAuras.ScanEvents(\"SL\", true)\n\naura_env.setButtonAttributes = function()\n    if InCombatLockdown() then\n        print(\"please reload for new teleport button\")\n        return\n    else\n        local i = 1\n        while GetSpellBookItemName(i, BOOKTYPE_SPELL) do\n            local spellName, spellSubName, spellID = GetSpellBookItemName(i, BOOKTYPE_SPELL)\n            if spellID == aura_env.spellID then break end\n            i = i + 1\n        end\n        aura_env.button:Show()\n        aura_env.button:RegisterForClicks(\"LeftButtonDown\", \"LeftButtonUp\")\n        aura_env.button:SetAttribute(\"type\", \"spell\")\n        aura_env.button:SetAttribute(\"spell\", aura_env.spellID)\n        aura_env.button:SetScript(\"OnEnter\", function(self)\n                GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n                GameTooltip:ClearLines()\n                GameTooltip:SetSpellBookItem(i, BOOKTYPE_SPELL)\n                GameTooltip:Show()\n        end)\n        aura_env.button:SetScript(\"OnLeave\", function(self)\n                GameTooltip:Hide()\n        end)\n    end\n    \nend\n\naura_env.setButtonAttributes()",
					["do_custom"] = true,
				},
				["finish"] = {
				},
				["init"] = {
					["custom"] = "aura_env.spellID = 354468",
					["do_custom"] = true,
				},
			},
		},
		["Cast Bar - LWA - Evoker"] = {
			["sparkWidth"] = 10,
			["iconSource"] = -1,
			["authorOptions"] = {
			},
			["preferToUpdate"] = true,
			["yOffset"] = 0,
			["anchorPoint"] = "CENTER",
			["sparkRotation"] = 0,
			["url"] = "https://wago.io/LuxthosEvokerDragonflight/36",
			["actions"] = {
				["start"] = {
					["do_message"] = false,
				},
				["init"] = {
					["custom"] = "aura_env.region.configGroup = \"cast_bar\"\n\nlocal bar = aura_env.region.bar\n\nlocal ticks = {}\nfor i=1,3 do\n    local tickMark = bar:CreateTexture()\n    tickMark:SetColorTexture(1, 1, 1, 1)\n    tickMark:SetSize(3, bar:GetHeight())\n    tickMark:SetPoint(\"CENTER\", bar, \"LEFT\", 0, 0)\n    tickMark:SetDrawLayer(\"ARTWORK\", 7);\n    tickMark:Hide()\n    \n    ticks[i] = tickMark\nend\n\nlocal function GetBaseDuration()\n    local base = IsPlayerSpell(369913) and 2.4 or 3\n    local haste = 1 + UnitSpellHaste(\"player\") / 100\n    \n    return base / haste\nend\n\nlocal function GetTotalDuration()\n    local _, _, _, startTime, endTime = UnitChannelInfo(\"player\")\n    \n    return (endTime - startTime) / 1000\nend\n\nlocal function UpdateTickMarks()\n    local relativeBaseDuration = (GetBaseDuration() / GetTotalDuration())\n    \n    for i, tickMark in ipairs(ticks) do\n        tickMark:Show()\n        tickMark:SetPoint(\"CENTER\", bar, \"LEFT\", (i / 3) * relativeBaseDuration * bar:GetWidth(), 0)\n    end\n    \n    if relativeBaseDuration > 0.99 then\n        ticks[3]:Hide()\n    end\nend\n\nlocal function HideTickMarks()\n    for _, tickMark in ipairs(ticks) do\n        tickMark:Hide()\n    end\nend\n\naura_env.trigger = UpdateTickMarks\naura_env.untrigger = HideTickMarks\n\n\n",
					["do_custom"] = true,
				},
