						["custom"] = "function(allstates, event, arg1, arg2, ...)\n    allstates[\"\"] = allstates[\"\"] or {\n        changed = true,\n        show = false,\n        percent = 0,\n    }\n    \n    if \"TRIGGER\" == event and arg2 then\n        local desc, matches, maximumValue = GetSpellDescription(372469), {}, 0\n        local buff = tonumber(arg2[\"\"] and arg2[\"\"].tooltip1 or \"0\")\n        \n        if buff and desc then\n            for t in desc:gmatch(\"(%d[%d%.,]*)\") do\n                if (LARGE_NUMBER_SEPERATOR == \",\") then\n                    t = t:gsub(\",\", \"\")\n                else\n                    t = t:gsub(\"%.\", \"\")\n                    t = t:gsub(\",\", \".\")\n                end\n                \n                tinsert(matches, tonumber(t))\n            end\n            \n            maximumValue = matches[2] or 0\n        end\n        \n        local show = buff > 0 and maximumValue > 0\n        local percent = 0\n        \n        if show then\n            percent = Round(buff / max(buff, maximumValue) * 100) or 0\n        end\n        \n        allstates[\"\"] = {\n            changed = true,\n            show = show,\n            percent = percent,\n        }\n        \n    end\n    return true\nend",
