					["custom"] = "local CRESTS = {\n    [0]={minLevel=415,maxLevel=447,shortName=\"Flightstones\",color=HEIRLOOM_BLUE_COLOR},\n    [1]={minLevel=441,maxLevel=450,shortName=\"Whelpling\",color=UNCOMMON_GREEN_COLOR,achieve=19326},\n    [2]={minLevel=454,maxLevel=463,shortName=\"Drake\",color=RARE_BLUE_COLOR,achieve=19397},\n    [3]={minLevel=467,maxLevel=476,shortName=\"Wyrm\",color=ITEM_EPIC_COLOR,achieve=19398},\n    [4]={minLevel=480,maxLevel=489,shortName=\"Aspect\",color=ITEM_LEGENDARY_COLOR},\n}\n\nlocal UPGRADE_BONUSES = {\n    {id=9544,level=1,max=8,name=\"Explorer\",ilvl=415,crest=CRESTS[0]},\n    {id=9545,level=2,max=8,name=\"Explorer\",ilvl=418,crest=CRESTS[0]},\n    {id=9546,level=3,max=8,name=\"Explorer\",ilvl=421,crest=CRESTS[0]},\n    {id=9547,level=4,max=8,name=\"Explorer\",ilvl=424,crest=CRESTS[0]},\n    {id=9548,level=5,max=8,name=\"Explorer\",ilvl=428,crest=CRESTS[0]},\n    {id=9549,level=6,max=8,name=\"Explorer\",ilvl=431,crest=CRESTS[0]},\n    {id=9550,level=7,max=8,name=\"Explorer\",ilvl=434,crest=CRESTS[0]},\n    {id=9551,level=8,max=8,name=\"Explorer\",ilvl=437},\n    {id=9536,level=1,max=8,name=\"Adventurer\",ilvl=428,crest=CRESTS[0]},\n    {id=9537,level=2,max=8,name=\"Adventurer\",ilvl=431,crest=CRESTS[0]},\n    {id=9538,level=3,max=8,name=\"Adventurer\",ilvl=434,crest=CRESTS[0]},\n    {id=9539,level=4,max=8,name=\"Adventurer\",ilvl=437,crest=CRESTS[1]},\n    {id=9540,level=5,max=8,name=\"Adventurer\",ilvl=441,crest=CRESTS[1]},\n    {id=9541,level=6,max=8,name=\"Adventurer\",ilvl=444,crest=CRESTS[1]},\n    {id=9542,level=7,max=8,name=\"Adventurer\",ilvl=447,crest=CRESTS[1]},\n    {id=9543,level=8,max=8,name=\"Adventurer\",ilvl=450},\n    {id=9552,level=1,max=8,name=\"Veteran\",ilvl=441,crest=CRESTS[1]},\n    {id=9553,level=2,max=8,name=\"Veteran\",ilvl=444,crest=CRESTS[1]},\n    {id=9554,level=3,max=8,name=\"Veteran\",ilvl=447,crest=CRESTS[1]},\n    {id=9555,level=4,max=8,name=\"Veteran\",ilvl=450,crest=CRESTS[2]},\n    {id=9556,level=5,max=8,name=\"Veteran\",ilvl=454,crest=CRESTS[2]},\n    {id=9557,level=6,max=8,name=\"Veteran\",ilvl=457,crest=CRESTS[2]},\n    {id=9558,level=7,max=8,name=\"Veteran\",ilvl=460,crest=CRESTS[2]},\n    {id=9559,level=8,max=8,name=\"Veteran\",ilvl=463},\n    {id=9560,level=1,max=8,name=\"Champion\",ilvl=454,crest=CRESTS[2]},\n    {id=9561,level=2,max=8,name=\"Champion\",ilvl=457,crest=CRESTS[2]},\n    {id=9562,level=3,max=8,name=\"Champion\",ilvl=460,crest=CRESTS[2]},\n    {id=9563,level=4,max=8,name=\"Champion\",ilvl=463,crest=CRESTS[3]},\n    {id=9564,level=5,max=8,name=\"Champion\",ilvl=467,crest=CRESTS[3]},\n    {id=9565,level=6,max=8,name=\"Champion\",ilvl=470,crest=CRESTS[3]},\n    {id=9566,level=7,max=8,name=\"Champion\",ilvl=473,crest=CRESTS[3]},\n    {id=9567,level=8,max=8,name=\"Champion\",ilvl=476},\n    {id=9568,level=1,max=6,name=\"Hero\",ilvl=467,crest=CRESTS[3]},\n    {id=9569,level=2,max=6,name=\"Hero\",ilvl=470,crest=CRESTS[3]},\n    {id=9570,level=3,max=6,name=\"Hero\",ilvl=473,crest=CRESTS[3]},\n    {id=9571,level=4,max=6,name=\"Hero\",ilvl=476,crest=CRESTS[4]},\n    {id=9572,level=5,max=6,name=\"Hero\",ilvl=480,crest=CRESTS[4]},\n    {id=9581,level=6,max=6,name=\"Hero\",ilvl=483},\n    {id=9573,level=1,max=4,name=\"Myth\",ilvl=480,crest=CRESTS[4]},\n    {id=9574,level=2,max=4,name=\"Myth\",ilvl=483,crest=CRESTS[4]},\n    {id=9575,level=3,max=4,name=\"Myth\",ilvl=486,crest=CRESTS[4]},\n    {id=9576,level=4,max=4,name=\"Myth\",ilvl=489},\n}\n\nlocal UPGRADE_TIERS = {\n    Explorer={minLevel=415,maxLevel=437,color=ITEM_POOR_COLOR},\n    Adventurer={minLevel=428,maxLevel=450,color=WHITE_FONT_COLOR},\n    Veteran={minLevel=441,maxLevel=463,color=UNCOMMON_GREEN_COLOR},\n    Champion={minLevel=454,maxLevel=476,color=RARE_BLUE_COLOR},\n    Hero={minLevel=467,maxLevel=483,color=ITEM_EPIC_COLOR},\n    Myth={minLevel=480,maxLevel=489,color=ITEM_LEGENDARY_COLOR},\n}\n\nlocal SetValueToKey = function(list, field, valuesArray)\n    local newList = {}\n    for _,v in ipairs(list) do\n        local key = v\n        local data = true\n        if field then \n            key = v[field]\n        end\n        if tonumber(key) then \n            key = tonumber(key)\n        end\n        if valuesArray then\n            data = v\n        end\n        newList[key]=data\n    end\n    return newList\nend\nUPGRADE_BONUSES = SetValueToKey(UPGRADE_BONUSES, \"id\", true)\n\n\n-- process tooltip data\nlocal function ProcessTooltip(tooltip, data)   \n    local itemName, itemLink = TooltipUtil.GetDisplayedItem(tooltip)\n    if not itemLink then return end\n    \n    --Create ItemMixin from itemLink\n    local item = Item:CreateFromItemLink(itemLink)\n    if item:IsItemEmpty() then return end\n    local itemName, itemLink, itemLevel = item:GetItemName(), item:GetItemLink(), item:GetCurrentItemLevel()\n    if itemLevel < 415 then return end\n    \n    --Create bonusIDs table from item\n    local itemLinkValues = StringSplitIntoTable(\":\", itemLink)\n    local numBonusIDs = itemLinkValues[14]\n    if not tonumber(numBonusIDs) then return end\n    local bonusIDs = {unpack(itemLinkValues, 15, 15+numBonusIDs-1)}\n    bonusIDs = SetValueToKey(bonusIDs)\n    \n    --Match bonusID to UPGRADE_BONUSES\n    local bonusID = false\n    for id in pairs(bonusIDs) do\n        if UPGRADE_BONUSES[id] then\n            bonusID = id\n        end\n    end    \n    \n    --Loop over current tooltip lines\n    for i = 1, tooltip:NumLines() do\n        local line = _G[tooltip:GetName()..\"TextLeft\"..i]\n        local text = line:GetText()\n        \n        if text and text:match(\"(%a+) (%d+)/(%d+)$\") then\n            --Check if item is a Seasonal/Upgradable item\n            local tier,current,total\n            if bonusID then\n                tier = UPGRADE_BONUSES[bonusID].name\n                current = UPGRADE_BONUSES[bonusID].level\n                total = UPGRADE_BONUSES[bonusID].max\n            else\n                tier,current,total = text:match(\"(%a+) (%d+)/(%d+)$\")\n            end\n            if not tier or not current or not total then return end\n            \n            --Modify Upgrade Rank tooltip line\n            local minLevel = UPGRADE_TIERS[tier].minLevel\n            local maxLevel = UPGRADE_TIERS[tier].maxLevel\n            local range_colored = ITEM_POOR_COLOR:WrapTextInColorCode(\"(\" .. minLevel .. \"-\" .. maxLevel .. \")\")\n            if minLevel and maxLevel then\n                local newLineText = current .. \"/\" .. total .. \" \" .. tier .. \" \" .. range_colored\n                line:SetText(newLineText)\n                line:Show()\n            end\n            \n            --Add Crest required to upgrade\n            if bonusID and UPGRADE_BONUSES[bonusID].crest then\n                local crest = UPGRADE_BONUSES[bonusID].crest\n                if crest then\n                    local crestName = crest.shortName\n                    local crestName_colored = crest.color:WrapTextInColorCode(crestName)\n                    local achieve = crest.achieve and select(13, GetAchievementInfo(crest.achieve))\n                    local rightLineText = \"|A:2329:20:20:1:-1|a\"..(not achieve and crestName_colored or \"\")\n                    local rightLine = _G[tooltip:GetName()..\"TextRight\"..i]\n                    rightLine:SetText(rightLineText)\n                    rightLine:Show()\n                end\n            end \n        end\n    end\nend\n\n\nlocal function OnTooltipSetItem(tooltip, data)\n    ProcessTooltip(tooltip, data)\nend\n\nif not aura_env.region.hooked then\n    aura_env.region.hooked = true\n    TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item, OnTooltipSetItem)\nend",
