					["untrigger"] = {
					},
				}, -- [1]
				{
					["trigger"] = {
						["type"] = "custom",
						["custom_type"] = "event",
						["event"] = "Health",
						["subeventPrefix"] = "SPELL",
						["events"] = "PLAYER_ENTERING_WORLD, ACTIVE_TALENT_GROUP_CHANGED, ENCOUNTER_START",
						["genericShowOn"] = "showOnActive",
						["custom"] = "function()\n    --This trigger forces the WeakAura to run its initialization code when\n    --loading into a zone or when switching specs. It also forces talent\n    --information to be updated.\n    aura_env.updateTalents()\n    \n    aura_env.update()\nend",
						["subeventSuffix"] = "_CAST_START",
						["custom_hide"] = "custom",
					},
					["untrigger"] = {
					},
				}, -- [2]
				{
					["trigger"] = {
						["type"] = "custom",
						["custom_type"] = "event",
						["event"] = "Health",
						["subeventPrefix"] = "SPELL",
						["events"] = "CLEU:SPELL_AURA_APPLIED:SPELL_CAST_SUCCESS:SPELL_MISSED:SPELL_AURA_REMOVED:SPELL_AURA_REFRESH",
						["genericShowOn"] = "showOnActive",
						["custom"] = "function (event, timestamp, msg, _, sourceGUID, _, _, _, destGUID, _, _, _, spellID)\n    --This trigger listens for bleed events to record snapshots.\n    --This trigger also listens for changes in buffs to recalculate bleed damage.\n    local this = aura_env\n    \n    --Check for only relevant player events\n    if not this.buffID[spellID] and not this.debuffID[spellID] then return end\n    if not this.events[msg] then return end\n    if sourceGUID ~= this.pguid then return end\n    \n    --Handle AURA_APPLY and AURA_REFRESH as the same event type\n    if msg == \"SPELL_AURA_REFRESH\" then msg = \"SPELL_AURA_APPLIED\" end\n    \n    --Convert rake stun events into rake casts to handle corner case with prowl+rake\n    if spellID == 163505 and (msg==\"SPELL_MISSED\" or msg==\"SPELL_AURA_APPLIED\") then\n        spellID = 1822\n        msg = \"SPELL_CAST_SUCCESS\"\n    end\n    \n    --Listen for buff changes on player that affect snapshots\n    if destGUID == this.pguid then\n        if msg == \"SPELL_AURA_APPLIED\" then this.update() return\n        elseif msg == \"SPELL_AURA_REMOVED\" then\n            local spellName = this.buffID[spellID]\n            local dur = 0\n            --Add small timing window for buffs that can expire before cast\n            if spellName == \"bloodtalons\" then dur = 0.1\n            elseif spellName == \"prowl\" then dur = 0.1\n            elseif spellName == \"shadowmeld\" then dur = 0.1\n            elseif spellName == \"suddenAmbush\" then dur = 0.1\n            end\n            \n            if spellName then\n                this.buffs[spellName] = GetTime() + dur\n                this.nextUpdateDmg = GetTime() + dur + 0.01\n                return\n            end\n        end\n    end\n    \n    -- The following code handles application and expiration of bleeds\n    -- 1. Snapshot dmg on spell cast success\n    local fs = aura_env.feralSnapshots\n    if msg == \"SPELL_CAST_SUCCESS\" then\n        local spellName\n        if spellID == 1822 then spellName = \"rake\"\n        elseif spellID == 1079 then spellName = \"rip\"\n        elseif spellID == 285381 then spellName = \"rip\"\n        elseif spellID == 106830 then spellName = \"thrash\"\n        elseif spellID == 155625 then spellName = \"moonfire\"\n        elseif spellID == 203242 then spellName = \"ripAndTear\"\n        end\n        \n        if spellName then\n            this.update()\n            --Add exception logic for Rip And Tear\n            if spellName == \"ripAndTear\" then\n                fs[\"rip\"][\"onCast\"] = fs[\"rip\"][\"current\"]\n                fs[\"rake\"][\"onCast\"] = fs[\"rake\"][\"current\"]\n                return\n            end\n            fs[spellName][\"onCast\"] = fs[spellName][\"current\"]\n            return\n        end\n        \n        --2. Record snapshot for target if and when the bleed is applied\n    elseif msg == \"SPELL_AURA_APPLIED\" then\n        local spellName\n        if spellID == 155722 then spellName = \"rake\"\n        elseif spellID == 1079 then spellName = \"rip\"\n        elseif spellID == 405233 then spellName = \"thrash\"\n        elseif spellID == 155625 then spellName = \"moonfire\"\n        end\n        \n        if spellName then\n            fs[spellName][destGUID] = fs[spellName][\"onCast\"]\n            aura_env.updateModifiers(spellName, destGUID);\n            return\n        end\n        \n        --3. Remove snapshot for target when bleed expires\n    elseif msg == \"SPELL_AURA_REMOVED\" then\n        local spellName\n        if spellID == 155722 then spellName = \"rake\"\n        elseif spellID == 1079 then spellName = \"rip\"\n        elseif spellID == 405233 then spellName = \"thrash\"\n        elseif spellID == 155625 then spellName = \"moonfire\"\n        end\n        \n        if spellName then\n            fs[spellName][destGUID] = nil\n            this.feralModifiers[spellName][destGUID] = nil;\n            WeakAuras.ScanEvents(\"MODIFIER_UPDATE\", this.feralModifiers)\n            WeakAuras.ScanEvents(\"BLEEDPOWER_UPDATE\", this.feralSnapshots)\n            return\n        end\n    end\nend",
						["subeventSuffix"] = "_CAST_START",
						["custom_hide"] = "custom",
					},
					["untrigger"] = {
