				},
			},
			["alpha"] = 1,
			["useAdjustededMax"] = false,
			["url"] = "https://wago.io/LuxthosDruidDragonflight/90",
			["source"] = "import",
			["xOffset"] = 0,
			["information"] = {
				["forceEvents"] = true,
				["ignoreOptionsEventErrors"] = true,
			},
			["displayIcon"] = "Interface\\Icons\\Ability_Druid_CatForm",
			["actions"] = {
				["start"] = {
				},
				["init"] = {
					["custom"] = "--Feral Bleed Power r20 by MoonBunnie for 9.0.0\n--Maintained by Drufearr for 10.1.0\n--Visit https://wago.io/Syz8eBzY-\n--for more info and the latest versions.\n\n--Initialize variables and parameters\nlocal this = aura_env\nthis.pguid = UnitGUID(\"player\")\nthis.cleanUpTimer = nil\nthis.lastUpdate = 0\nthis.nextUpdateDmg = nil\n\n--Create table for bleed power snapshot values\nthis.power = {\n    [\"tigersFury\"] = 1.15,\n    --[\"savageRoar\"] = 1.15,\n    [\"bloodtalons\"] = 1.25,\n    [\"momentOfClarity\"] = 1.15, --clearcasting\n    [\"stealth\"] = 1.6\n}\n\n--Create Talent tracking table\nthis.talents = {\n    --[\"savageRoar\"] = false,\n    [\"bloodtalons\"] = false,\n    [\"momentOfClarity\"] = false,\n    [\"carnivorousInstincs\"] = false\n}\n\n--Create Talent ID table\nthis.talentID = {\n    --[21702] = \"savageRoar\",\n    [319439] = \"bloodtalons\",\n    [236068] = \"momentOfClarity\",\n    [390902] = \"carnivorousInstincts\"\n}\n\n--Create Buff tracking table\nthis.buffs = {\n    [\"tigersFury\"] = 0,\n    --[\"savageRoar\"] = 0,\n    [\"bloodtalons\"] = 0,\n    [\"momentOfClarity\"] = 0, --clearcasting\n    [\"prowl\"] = 1,\n    [\"shadowmeld\"] = 1,\n    [\"suddenAmbush\"] = 0,\n}\n\n--Create Combat Log Event filter table\nthis.events = {\n    [\"SPELL_AURA_APPLIED\"] = true,\n    [\"SPELL_AURA_REFRESH\"] = true,\n    [\"SPELL_AURA_REMOVED\"] = true,\n    [\"SPELL_CAST_SUCCESS\"] = true,\n    [\"SPELL_MISSED\"] = true\n}\n\n--Create Buff ID filter table\nthis.buffID = {\n    [5217] = \"tigersFury\",\n    --[52610] = \"savageRoar\",\n    [145152] = \"bloodtalons\",\n    [5215] = \"prowl\",\n    [102547] = \"prowl\",\n    [58984] = \"shadowmeld\",\n    [391974] = \"suddenAmbush\",\n}\n\n--Create Debuff ID filter table\nthis.debuffID = {\n    [163505] = \"rake\", --stun effect\n    [1822] = \"rake\", --initial dmg\n    [1079] = \"rip\",\n    [106830] = \"thrash\", -- spellid\n    [405233] = \"thrash\", -- dot\n    [155722] = \"rake\", --dot\n    [155625] = \"moonfire\",\n    [203242] = \"ripAndTear\",\n    [285381] = \"primalWrath\"\n}\n\n--Initialize tables to hold all snapshot data\nthis.feralSnapshots = {\n    [\"rake\"] = {},\n    [\"rip\"] = {},\n    [\"thrash\"] = {},\n    [\"moonfire\"] = {}\n}\n\n-- new modifier tracker for remastered pawkets'\nthis.feralModifiers = {\n    [\"rake\"] = {},\n    [\"rip\"] = {},\n    [\"thrash\"] = {},\n    [\"moonfire\"] = {}\n}\n\nlocal function howManyPoints(spellId)\n    local configId = C_ClassTalents.GetActiveConfigID()\n    if configId then\n        local configInfo = C_Traits.GetConfigInfo(configId)\n        for _, treeId in ipairs(configInfo.treeIDs) do\n            local nodes = C_Traits.GetTreeNodes(treeId)\n            for _, nodeId in ipairs(nodes) do\n                local node = C_Traits.GetNodeInfo(configId, nodeId)\n                if node and node.ID ~= 0 then\n                    for _, talentId in ipairs(node.entryIDs) do\n                        local entryInfo = C_Traits.GetEntryInfo(configId, talentId)\n                        local definitionInfo = C_Traits.GetDefinitionInfo(entryInfo.definitionID)\n                        if definitionInfo.spellID == spellId then\n                            return node.activeEntry and node.currentRank or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    return 0\nend\n\n--Create update function for checking active talents\nthis.updateTalents = function()\n    local t = this.talents\n    local tID = this.talentID\n    local b = this.buffs\n    local bID = this.buffID\n    \n    --Use talent ID table to check if talent is selected\n    for id,name in pairs(tID) do\n        t[name] = howManyPoints(id) and howManyPoints(id) > 0 or false\n    end\n    \n    --Add or remove clearcasting in the buff filter list for Moment of Clarity\n    if t.momentOfClarity then\n        bID[135700] = \"momentOfClarity\"\n    else\n        bID[135700] = nil\n        b.momentOfClarity = 0\n    end\n    \n    if t.carnivorousInstincts then\n        this.power.tigersFury = 1.15 + 0.06 * howManyPoints(390902)\n    end\nend\n\nthis.updateTalents()\n\n--Create update function for checking for buffs\nthis.update = function()\n    local b = this.buffs\n    local bID = this.buffID\n    local t = this.talents\n    local now = GetTime()\n    \n    this.lastUpdate = now\n    \n    --Use Buff ID filter table to query for buff expiration times if present\n    for id,name in pairs(bID) do\n        if t[name] == true or t[name] == nil then\n            b[name] = select(6,WA_GetUnitAura(\"player\", id, \"PLAYER|HELPFUL\")) or b[name]\n        end\n    end\n    \n    this.updateDmg()\nend\n\n--Create update function for calculating current snapshot strength\nthis.updateDmg = function()\n    local b = this.buffs\n    local p = this.power\n    local now = GetTime()\n    local multi = {\n        [\"general\"] = 1,\n        [\"bt\"] = 1,\n        [\"moc\"] = 1,\n        [\"stealth\"] = 1\n    }\n    \n    if b.tigersFury > now then multi.general = p.tigersFury end\n    --if b.savageRoar > now then multi.general = multi.general * p.savageRoar end\n    if b.bloodtalons > now then multi.bt = p.bloodtalons end\n    if b.momentOfClarity > now then multi.moc = p.momentOfClarity end\n    if b.prowl > now or b.shadowmeld > now or b.prowl == 0 or b.shadowmeld == 0 or b.suddenAmbush > now then\n        multi.stealth = p.stealth\n    end\n    \n    --Record snapshot values for each spell\n    this.feralSnapshots.rip.current = multi.general*multi.bt\n    this.feralSnapshots.rip.current5CP = multi.general*multi.bt\n    this.feralSnapshots.rake.current = multi.general*multi.stealth\n    this.feralSnapshots.thrash.current = multi.general*multi.moc\n    this.feralSnapshots.moonfire.current = multi.general    \n    WeakAuras.ScanEvents(\"MODIFIER_UPDATE\", this.feralModifiers)\n    WeakAuras.ScanEvents(\"BLEEDPOWER_UPDATE\", this.feralSnapshots)\nend\n--Potato added?\nthis.updateModifiers = function(spell, guid)\n    local b = this.buffs\n    local p = this.power\n    local now = GetTime()\n    local multi = {\n        [\"general\"] = 1,\n        [\"bt\"] = 1,\n        [\"moc\"] = 1,\n        [\"stealth\"] = 1\n    }\n    \n    local mods = {\n        ['rip'] = {\n            ['bt'] = true, ['general'] = true\n        },\n        ['rake'] = {\n            ['general'] = true, ['stealth'] = true\n        },\n        ['thrash'] = {\n            ['general'] = true, ['moc'] = true\n        },\n        ['moonfire'] = {\n            ['general'] = true\n        },\n    }\n    \n    if b.tigersFury > now then multi.general = p.tigersFury end\n    --if b.savageRoar > now then multi.general = multi.general * p.savageRoar end\n    if b.bloodtalons > now then multi.bt = p.bloodtalons end\n    if b.momentOfClarity >= now then multi.moc = p.momentOfClarity end\n    if b.prowl > now or b.shadowmeld > now or b.prowl == 0 or b.shadowmeld == 0 or b.suddenAmbush > now then\n        multi.stealth = p.stealth\n    end\n    \n    this.feralModifiers[spell][guid] = this.feralModifiers[spell][guid] or {};\n    for k in pairs(mods[spell]) do\n        this.feralModifiers[spell][guid][k] = multi[k] ~= 1;\n    end\n    WeakAuras.ScanEvents(\"MODIFIER_UPDATE\", this.feralModifiers)\n    WeakAuras.ScanEvents(\"BLEEDPOWER_UPDATE\", this.feralSnapshots)\nend\n\nthis.removeModifiers = function(spell, guid)\n    this.feralModifiers[spell][guid] = nil;\n    WeakAuras.ScanEvents(\"MODIFIER_UPDATE\", this.feralModifiers)\n    WeakAuras.ScanEvents(\"BLEEDPOWER_UPDATE\", this.feralSnapshots)\nend\n\n\nthis.update()\n\n--Create function for handling clean up of the snapshot table\nthis.cleanUp = function()\n    --Cancel existing scheduled cleanup first if there is one\n    if this.cleanUpTimer then this.cancelCleanUp() end\n    \n    this.cleanupTimer = C_Timer.NewTimer(30,\n        function()\n            if not UnitAffectingCombat(\"player\") then\n                this.feralSnapshots = {\n                    [\"rake\"] = {},\n                    [\"rip\"] = {},\n                    [\"thrash\"] = {},\n                    [\"moonfire\"] = {}\n                }\n                this.feralModifiers = {\n                    [\"rake\"] = {},\n                    [\"rip\"] = {},\n                    [\"thrash\"] = {},\n                    [\"moonfire\"] = {}\n                }\n                \n                WeakAuras.ScanEvents(\"MODIFIER_UPDATE\", this.feralModifiers)\n                WeakAuras.ScanEvents(\"BLEEDPOWER_UPDATE\", this.feralSnapshots)\n            end\n        end\n    )\nend\n\n--Create clean up function\nthis.cancelCleanUp = function()\n    if this.cleanupTimer then\n        this.cleanupTimer:Cancel()\n        this.cleanupTimer = nil\n    end\nend",
