			["customText"] = "function()\n    --set spell to display by name\n    local name = \"rake\"\n    \n    local fs = aura_env.feralSnapshots\n    local unit = UnitGUID(\"target\")\n    if fs and fs[name] and fs[name][unit] then\n        --round value to nearest %\n        local val = floor(fs[name][\"current\"]/fs[name][unit]*100+0.5)\n        if val > 105 then --Change font to green if above this value\n            return format(\"|cFF00FF00%d\", val)\n        elseif val < 95 then --Change font to red if below this value\n            return format(\"|cFFFF0000%d\", val)\n        else --Default grey font color\n            return format(\"|cFF999999%d\", val)\n        end\n    end\n    --Display the string or value below if no snapshot exists on target\n    return ''\nend",
