						["customVariables"] = "{ power = \"number\" }",
						["custom"] = "function(allstates, event, feralSnapshots)\n    if event == \"BLEEDPOWER_UPDATE\" and feralSnapshots ~= nil then       \n        aura_env.feralSnapshots = feralSnapshots\n        \n        local name = \"rake\"\n        local unit = UnitGUID(\"target\")\n        local val = 0\n        \n        if unit and feralSnapshots[name] and feralSnapshots[name][unit] then\n            val = feralSnapshots[name][\"current\"]/feralSnapshots[name][unit]\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            power = val\n        }\n        \n        return true \n    end\nend",
