			["cooldownSwipe"] = true,
			["url"] = "https://wago.io/xzvpUDanJ/6",
			["icon"] = true,
			["triggers"] = {
				{
					["trigger"] = {
						["type"] = "custom",
						["subeventSuffix"] = "_CAST_START",
						["customVariables"] = "",
						["event"] = "Health",
						["unit"] = "player",
						["custom_type"] = "stateupdate",
						["subeventPrefix"] = "SPELL",
						["custom"] = "function (allStates, e, arg1)\n    \n    if e == \"OPTIONS\" then\n        local keys = aura_env.getFakeData()\n        allStates = aura_env.getStates(allStates,keys)\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_KEYS_OBTAINED\" then\n        local keys = arg1\n        allStates = aura_env.getStates(allStates,keys)\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_GO\" then\n        aura_env.winningIndex = 0\n        aura_env.spinning = true\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_STOP\" then\n        aura_env.spinning = false\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_KEYS_DECIDED\" then\n        aura_env.winningIndex = arg1\n    end\n    \n    return true\nend",
						["names"] = {
						},
						["check"] = "event",
						["events"] = "PSY_WHEEL_DECIDE_KEYS_OBTAINED PSY_WHEEL_DECIDE_SPIN_GO PSY_WHEEL_DECIDE_SPIN_STOP PSY_WHEEL_DECIDE_KEYS_DECIDED",
						["spellIds"] = {
