						["custom_hide"] = "custom",
						["events"] = "CLEU:SPELL_HEAL:SWING_DAMAGE:SWING_MISSED:RANGE_DAMAGE:RANGE_MISSED:SPELL_DAMAGE:SPELL_MISSED:SPELL_PERIODIC_DAMAGE:SPELL_PERIODIC_MISSED:SPELL_BUILDING_DAMAGE:SPELL_BUILDING_MISSED",
						["spellIds"] = {
